package com.infosys.carbonfootprint.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.*;
@Entity @Table(name="articles") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Article { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=200) private String title; @Column(nullable=false,length=600) private String shortDescription; @Column(nullable=false,columnDefinition="TEXT") private String content; @Column(nullable=false,length=100) private String category; private String coverImage; @Column(nullable=false,length=120) private String author; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private ArticleStatus status=ArticleStatus.DRAFT; @Column(nullable=false) @Builder.Default private boolean visibleToUsers=false; private LocalDateTime publishedAt; @CreationTimestamp private LocalDateTime createdAt; @UpdateTimestamp private LocalDateTime updatedAt; }